import{_ as s,o as a,c as e,a2 as t}from"./chunks/framework.CqGS6Fr9.js";const c=JSON.parse('{"title":"Discord-бот","description":"","frontmatter":{"pageId":"admins/discord","contentRevision":2},"headers":[],"relativePath":"ru/admins/discord.md","filePath":"ru/admins/discord.md"}'),l={name:"ru/admins/discord.md"};function n(h,i,r,p,d,k){return a(),e("div",null,[...i[0]||(i[0]=[t(`<h1 id="discord-бот" tabindex="-1">Discord-бот <a class="header-anchor" href="#discord-бот" aria-label="Permalink to &quot;Discord-бот&quot;">​</a></h1><p>Применимость: Rimlink 0.8.1 · RimWorld 1.7 · протокол 1.</p><h2 id="usage" tabindex="-1">Как пользоваться <a class="header-anchor" href="#usage" aria-label="Permalink to &quot;Как пользоваться {#usage}&quot;">​</a></h2><p>Бот — отдельный процесс/контейнер с секцией RimlinkBot. Server.Url указывает HTTPS сервера, ApiToken — отдельный именованный серверный токен с нужными scope. StateFile сохраняет позицию feed, его каталог должен быть постоянным.</p><p>В Discord Developer Portal создай бота, включи необходимый Message Content intent для чат-моста, добавь его в выбранную гильдию с минимальными правами. Задай Discord.Token, GuildId, Language (en/ru), ModeratorRoleIds, AdminRoleIds и id каналов Server/Raids/Market/Moderation/Chat. Нулевые id из примера не являются готовой конфигурацией.</p><p>Для TLS настрой CertificateSha256 (pin) либо доверенную цепочку с CertificateName при необходимости. Проверь чтение статуса, ограничения ролей и публичный чат на тестовом канале, затем включай мост.</p><h2 id="bot-accept" tabindex="-1">Запуск бота с минимальными правами <a class="header-anchor" href="#bot-accept" aria-label="Permalink to &quot;Запуск бота с минимальными правами {#bot-accept}&quot;">​</a></h2><p>Создай отдельный токен сервера и отдельный Discord bot token; заполни ненулевые guild/channel id и role id. Нужные server scopes определяют доступ к API, Discord-роли — кому разрешены команды в guild. Совпадение имён ролей не создаёт серверное право.</p><p>Сначала проверь status и отказ команды для обычного участника в тестовом канале. Затем включи публичный мост, проверь направление сообщений и запрет личного/альянсного канала. Для Message Content нужен intent в Developer Portal. Сохраняй StateFile в постоянном каталоге, иначе restart теряет позицию feed.</p><p>Если бот видит 401/403, исправляй токен/scope, не выдавай сразу admin. Если TLS не проходит, сверяй pin/имя/цепочку; Insecure=true не production-решение.</p><h3 id="полныи-путь-запуска-из-исходников" tabindex="-1">Полный путь запуска из исходников <a class="header-anchor" href="#полныи-путь-запуска-из-исходников" aria-label="Permalink to &quot;Полный путь запуска из исходников&quot;">​</a></h3><ol><li>Нужны checkout Rimlink той же версии, SDK из global.json, доступный HTTPS-сервер и Discord application. В Developer Portal включи Message Content; приглашение использует scopes bot и applications.commands и права View Channels, Send Messages, Add Reactions, Read Message History. Не выдавай Administrator.</li><li>Собери отдельный каталог (не каталог уже запущенного бота):</li></ol><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">dotnet publish src</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Rimlink.Discord </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">c Release </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">o .</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">build</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">discord</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">bot</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">Copy-Item</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> .</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">deploy</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">discord.appsettings.example.json .</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">build</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">discord</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">bot</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">appsettings.json</span></span></code></pre></div><ol start="3"><li>Открой <a href="https://github.com/Asofwar/rimlink/blob/main/deploy/discord.appsettings.example.json" target="_blank" rel="noreferrer">образец конфигурации</a>, заполни RimlinkBot в скопированном appsettings.json. Файл читается <strong>рядом с DLL</strong>, а не из произвольного рабочего каталога. Замени Url, оба токена, GuildId, роли и каналы; Channels.*=0 отключает группу. Укажи абсолютный StateFile в постоянном доступном на запись каталоге и проверенный CertificateSha256 либо доверенную цепочку/имя. Не коммить рабочий файл с секретами.</li><li>Минимальные серверные scopes: read — события и /status, /online, /market; read + chat — двусторонний публичный мост; moderate + chat — ещё /player и модерация; admin — только если нужны административные команды. Discord-роли задаются отдельно. Токен из Admin:Tokens сервера должен совпасть с Server:ApiToken бота.</li><li>При необходимости переопредели несекретные поля окружением; секреты передавай через защищённое окружение службы, не вставляй их в историю терминала:</li></ol><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">env:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">RimlinkBot__Server__Url </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;https://play.example.com:25560&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">$</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">env:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">RimlinkBot__StateFile </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;E:/RimlinkData/discord/feed-state&#39;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">dotnet .</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">build</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">discord</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">bot</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">/</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">rimlink</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">discord.dll</span></span></code></pre></div><ol start="6"><li>Ожидаемый результат: процесс остаётся запущен, /status отвечает в тестовой гильдии, обычному участнику отказано в /kick, двусторонний тестовый публичный чат проходит с chat-scope, а личный/альянсный не появляется. Отсутствующие токены останавливают процесс при проверке конфигурации; 401/403/TLS ошибки лечат настройкой, не отключением защиты.</li><li>Остановка — Ctrl+C в этой консоли либо штатная остановка службы. Перед обновлением сохрани appsettings.json и StateFile; после старта с тем же StateFile бот продолжит feed. При gap перечитай текущее состояние: потерянные события не восстанавливаются выдуманными сообщениями. Не удаляй state-файл ради устранения ошибки входа.</li></ol><p>Это инструкция запуска, не отчёт о выполненном подключении к живому Discord.</p><h2 id="limits" tabindex="-1">Ограничения и безопасность <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Ограничения и безопасность {#limits}&quot;">​</a></h2><p>Discord.Token и Server.ApiToken — разные секреты. Insecure=false по умолчанию; true только для изолированной сети. Серверные scopes и Discord-роли независимы. Мост пересылает публичный чат, не личные/союзные сообщения. Рестарт/gap требует перечитать состояние, а не выдумывать пропущенные события.</p><h2 id="related" tabindex="-1">См. также <a class="header-anchor" href="#related" aria-label="Permalink to &quot;См. также {#related}&quot;">​</a></h2><ul><li><a href="./security-auth">TLS, вход и права</a></li><li><a href="./monitoring">Мониторинг и журнал событий</a></li><li><a href="./../players/chat-pings">Чат, сообщения и пинги</a></li></ul>`,21)])])}const E=s(l,[["render",n]]);export{c as __pageData,E as default};
